"""Bookings API: 3 cases, one test each."""

import pytest

from api_test_framework import Expect, unique_id


@pytest.mark.functional
@pytest.mark.smoke
@pytest.mark.crud
@pytest.mark.writes
@pytest.mark.case("TC010")
@pytest.mark.priority("P1")
def test_tc010_the_passenger_name_can_be_changed(api, context):
    """The passenger name can be changed. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Ravi Kumar {unique}",
        "email": f"ravi.{unique}@testdata.example",
        "amount": 300,
    })
    Expect(response).status_is(201).field_equals("status", "active")
    context.remember("pnr", response.value("pnr"))
    # 2. PUT /bookings/{{pnr}}
    response = api.put(f"/bookings/{context.get('pnr')}", json={
        "passenger_name": "Ravi K",
        "email": f"ravi.{unique}@testdata.example",
    })
    Expect(response).status_is(200).field_equals("passenger_name", "Ravi K")
    # 3. GET /bookings/{{pnr}}
    response = api.get(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(200).field_equals("passenger_name", "Ravi K").field_equals("amount", 300)


@pytest.mark.functional
@pytest.mark.crud
@pytest.mark.writes
@pytest.mark.case("TC011")
@pytest.mark.priority("P2")
def test_tc011_a_deleted_booking_cant_be_read(api, context):
    """A deleted booking can't be read. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Ravi Kumar {unique}",
        "email": f"ravi.{unique}@testdata.example",
        "amount": 300,
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. DELETE /bookings/{{pnr}}
    response = api.delete(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(204)
    # 3. GET /bookings/{{pnr}}
    response = api.get(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(404).field_equals("error.code", "booking_not_found")


@pytest.mark.functional
@pytest.mark.crud
@pytest.mark.negative
@pytest.mark.writes
@pytest.mark.case("TC012")
@pytest.mark.priority("P2")
def test_tc012_the_amount_cant_be_changed(api, context):
    """The amount can't be changed. Criteria: AC-1."""
    unique = unique_id()
    # 1. POST /bookings
    response = api.post("/bookings", json={
        "passenger_name": f"Ravi Kumar {unique}",
        "email": f"ravi.{unique}@testdata.example",
        "amount": 300,
    })
    Expect(response).status_is(201)
    context.remember("pnr", response.value("pnr"))
    # 2. PUT /bookings/{{pnr}}
    response = api.put(f"/bookings/{context.get('pnr')}", json={
        "passenger_name": "Ravi K",
        "email": f"ravi.{unique}@testdata.example",
        "amount": 1,
    })
    Expect(response).status_is(422).field_equals("error.code", "invalid_request")
    # 3. GET /bookings/{{pnr}}
    response = api.get(f"/bookings/{context.get('pnr')}")
    Expect(response).status_is(200).field_equals("amount", 300)
